package com.bplus.share;
import android.app.*;import android.content.*;import android.net.nsd.*;import android.net.wifi.WifiManager;import android.os.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
public class NearbyActivity extends Activity {
 private final java.util.ArrayList<AlertDialog> openDialogs=new java.util.ArrayList<>();private NsdManager nsd;private NsdManager.RegistrationListener registration;private NsdManager.DiscoveryListener discovery;private WifiManager.MulticastLock lock;private LinearLayout list;private TextView state;private final Handler handler=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean active;private boolean requesting;private final Set<String> found=new HashSet<>(),dialogs=new HashSet<>();private volatile String outgoingId="",outgoingSecret="",outgoingIp="";
 private final Runnable poll=new Runnable(){public void run(){if(!active)return;for(NearbyGate.Request r:Nearby.gate.pending(System.currentTimeMillis()))if(dialogs.add(r.id))incoming(r);handler.postDelayed(this,800);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);Profile.init();LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.nearby_title),true,null));state=Ui.t(this,getString(R.string.nearby_notice),13,Ui.dim,App.cairoSB);Ui.pad(state,20,14,20,14,this);root.addView(state);ScrollView sc=new ScrollView(this);list=Ui.col(this);Ui.pad(list,20,0,20,20,this);sc.addView(list);root.addView(sc,Ui.lpW1());TextView qr=Ui.ghost(this,getString(R.string.qr_fallback));Ui.pad(qr,20,16,20,16,this);root.addView(qr);qr.setOnClickListener(v->startActivity(new Intent(this,DevicesActivity.class)));setContentView(root);}
 @Override protected void onResume(){super.onResume();start();}
 private void start(){active=true;Nearby.gate.visible(true);if(Net.localIp(this)==null){state.setText(getString(R.string.no_lan));return;}try{nsd=(NsdManager)getSystemService(NSD_SERVICE);lock=((WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE)).createMulticastLock("bplus-nearby");lock.setReferenceCounted(false);lock.acquire();registration=new NsdManager.RegistrationListener(){public void onServiceRegistered(NsdServiceInfo i){}public void onRegistrationFailed(NsdServiceInfo i,int e){showError("Registration "+e);}public void onServiceUnregistered(NsdServiceInfo i){}public void onUnregistrationFailed(NsdServiceInfo i,int e){}};NsdServiceInfo info=new NsdServiceInfo();info.setServiceName("Bplus-"+Store.get("deviceId",""));info.setServiceType("_bplusshare._tcp.");info.setPort(Store.PORT);nsd.registerService(info,NsdManager.PROTOCOL_DNS_SD,registration);
 discovery=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String s){}public void onDiscoveryStopped(String s){}public void onStartDiscoveryFailed(String s,int e){showError("Discovery "+e);}public void onStopDiscoveryFailed(String s,int e){}public void onServiceLost(NsdServiceInfo i){}public void onServiceFound(NsdServiceInfo i){if(!i.getServiceName().startsWith("Bplus-")||i.getServiceName().equals("Bplus-"+Store.get("deviceId","")))return;nsd.resolveService(i,new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo s,int e){}public void onServiceResolved(NsdServiceInfo s){if(!active||s.getHost()==null)return;String ip=s.getHost().getHostAddress();if(ip==null||ip.contains(":"))return;worker.execute(()->load(ip));}});}};nsd.discoverServices("_bplusshare._tcp.",NsdManager.PROTOCOL_DNS_SD,discovery);handler.post(poll);handler.postDelayed(()->{if(active&&found.isEmpty())state.setText(getString(R.string.nearby_empty));},12000);
 }catch(Exception e){showError(e.getClass().getSimpleName());}}
 private void showError(String e){runOnUiThread(()->state.setText(getString(R.string.nearby_failed)+"\n"+e));}
 private void load(String ip){try{JSONObject profile=Profile.clean(Nearby.call(ip,"/nearby/profile",new JSONObject()));if(profile.optString("id").equals(Store.get("deviceId","")))return;if(Store.get("blocked_"+profile.optString("id"),"0").equals("1"))return;runOnUiThread(()->{if(!active||!found.add(profile.optString("id")))return;LinearLayout row=Ui.row(this);row.addView(Profile.avatar(this,profile,48));LinearLayout meta=Ui.col(this);Ui.pad(meta,12,12,12,12,this);meta.addView(Ui.t(this,profile.optString("name"),16,Ui.text,App.cairoB));meta.addView(Ui.t(this,"@"+profile.optString("username"),12,Ui.dim,App.cairoSB));row.addView(meta,Ui.lpw(1));TextView add=Ui.ghost(this,getString(R.string.request_pair));add.setTextSize(11);add.setMaxWidth(Ui.dp(this,112));row.addView(add);add.setOnClickListener(v->request(ip,profile));list.addView(row);});}catch(Exception ignored){}}
 private void request(String ip,JSONObject profile){if(requesting||!outgoingId.isEmpty()){android.widget.Toast.makeText(this,getString(R.string.request_wait),0).show();return;}new AlertDialog.Builder(this).setTitle(getString(R.string.request_pair)).setMessage(profile.optString("name")+"\n@"+profile.optString("username")+"\n"+getString(R.string.identity_notice)).setNegativeButton(getString(R.string.cancel),null).setPositiveButton(getString(R.string.request_pair),(d,n)->{requesting=true;worker.execute(()->{
  String secret=UUID.randomUUID().toString().replace("-","");try{JSONObject body=new JSONObject();body.put("secret",secret);body.put("profile",Profile.local());JSONObject response=Nearby.call(ip,"/nearby/request",body);if(!active){JSONObject end=new JSONObject();end.put("request",response.getString("request"));end.put("secret",secret);Nearby.call(ip,"/nearby/cancel",end);return;}outgoingId=response.getString("request");outgoingSecret=secret;outgoingIp=ip;runOnUiThread(()->pending(profile));}catch(Exception e){showError(e.getMessage());}finally{runOnUiThread(()->requesting=false);}
 });}).show();}
 private void pending(JSONObject profile){if(!active){cancel();return;}state.setText(getString(R.string.request_wait)+" · "+profile.optString("name"));AlertDialog dialog=new AlertDialog.Builder(this).setMessage(getString(R.string.request_wait)).setNegativeButton(getString(R.string.cancel),(d,n)->cancel()).create();dialog.setCancelable(false);openDialogs.add(dialog);dialog.show();String id=outgoingId,secret=outgoingSecret,ip=outgoingIp;
 worker.execute(()->{long deadline=System.currentTimeMillis()+60000;String result="timeout";try{while(active&&outgoingId.equals(id)&&System.currentTimeMillis()<deadline){Thread.sleep(1400);JSONObject b=new JSONObject();b.put("request",id);b.put("secret",secret);JSONObject r=Nearby.call(ip,"/nearby/status",b);String status=r.optString("status");if(status.equals("accepted")&&active&&outgoingId.equals(id)){JSONObject peer=Profile.clean(r.getJSONObject("profile"));peer.put("token",r.getString("token"));peer.put("ip",ip);peer.put("port",Store.PORT);b.put("token",Store.token());Nearby.call(ip,"/nearby/confirm",b);Store.upsertPeer(peer);result="paired";break;}if(!status.equals("pending")){result=status;break;}}}catch(Exception e){result=e.getClass().getSimpleName()+": "+e.getMessage();}String finalResult=result;outgoingId="";runOnUiThread(()->{dialog.dismiss();if(active)state.setText(finalResult.equals("paired")?getString(R.string.phones_paired):getString(R.string.request_ended)+" · "+finalResult);});});}
 private void cancel(){String id=outgoingId,secret=outgoingSecret,ip=outgoingIp;outgoingId="";new Thread(()->{try{JSONObject b=new JSONObject();b.put("request",id);b.put("secret",secret);Nearby.call(ip,"/nearby/cancel",b);}catch(Exception ignored){}}).start();}
 private void incoming(NearbyGate.Request r){LinearLayout box=Ui.col(this);Ui.pad(box,22,14,22,14,this);box.addView(Profile.avatar(this,r.profile,64));box.addView(Ui.t(this,r.profile.optString("name")+"\n@"+r.profile.optString("username"),18,Ui.text,App.cairoB));box.addView(Ui.t(this,getString(R.string.identity_notice)+"\n"+getString(R.string.accept_notice),13,Ui.dim,App.cairoSB));AlertDialog dialog=new AlertDialog.Builder(this).setTitle(getString(R.string.incoming_request)).setView(box).setPositiveButton(getString(R.string.accept_pair),(d,n)->decide(r,"accepted")).setNegativeButton(getString(R.string.decline_pair),(d,n)->decide(r,"declined")).setNeutralButton(getString(R.string.block_pair),(d,n)->{Store.set("blocked_"+r.profile.optString("id"),"1");decide(r,"blocked");}).setOnCancelListener(d->decide(r,"declined")).create();openDialogs.add(dialog);dialog.show();}
 private void decide(NearbyGate.Request r,String status){try{Nearby.gate.decide(r.id,status,System.currentTimeMillis());state.setText(getString(status.equals("accepted")?R.string.keep_nearby_open:R.string.request_ended));}catch(Exception e){showError(e.getMessage());}}
 @Override protected void onPause(){active=false;for(AlertDialog d:openDialogs)d.dismiss();openDialogs.clear();cancel();Nearby.gate.visible(false);handler.removeCallbacksAndMessages(null);try{if(discovery!=null)nsd.stopServiceDiscovery(discovery);}catch(Exception ignored){}try{if(registration!=null)nsd.unregisterService(registration);}catch(Exception ignored){}try{if(lock!=null&&lock.isHeld())lock.release();}catch(Exception ignored){}found.clear();list.removeAllViews();super.onPause();}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
